package agent

import("crypto/sha256";"encoding/hex";"net/http";"net/http/httptest";"os";"path/filepath";"testing";"github.com/jiejhong/GooseCab/internal/eventbus";"github.com/jiejhong/GooseCab/internal/gateway";"github.com/jiejhong/GooseCab/internal/store")
func TestTwoAgentsAndLocalDataPlane(t *testing.T){s,e:=store.Open(filepath.Join(t.TempDir(),"db.sqlite"));if e!=nil{t.Fatal(e)};defer s.Close();h:=(&gateway.WS{Store:s,Bus:eventbus.New()}).Handler(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){http.NotFound(w,r)}));srv:=httptest.NewServer(h);defer srv.Close();url:="ws"+srv.URL[4:]+"/api/v1/agent/connect";a,e:=Dial(url,"smoke","agent-a",[]string{"cap.echo"});if e!=nil{t.Fatal(e)};defer a.Close();b,e:=Dial(url,"smoke","agent-b",nil);if e!=nil{t.Fatal(e)};defer b.Close();if e=a.Write(map[string]any{"type":"capability.announce","agent_id":"agent-a","capability_id":"cap.echo"});e!=nil{t.Fatal(e)};if e=a.Write(map[string]any{"type":"capability.invoke","request_id":"r1","capability_id":"cap.echo","payload":"hello"});e!=nil{t.Fatal(e)};if e=b.Write(map[string]any{"type":"capability.result","request_id":"r1","status":"completed"});e!=nil{t.Fatal(e)};seen:=map[string]bool{};for i:=0;i<8&&!seen["capability.result"];i++{m,e:=a.Read();if e!=nil{t.Fatal(e)};if typ,_:=m["type"].(string);typ!=""{seen[typ]=true}};if !seen["capability.result"]{t.Fatal("agent A did not observe result")}
src:=filepath.Join(t.TempDir(),"source.bin");dst:=filepath.Join(t.TempDir(),"target.bin");data:=[]byte("local-only payload for GooseCab");if e=os.WriteFile(src,data,0600);e!=nil{t.Fatal(e)};n,got,e:=CopyWithMode("direct",src,dst);if e!=nil{t.Fatal(e)};want:=sha256.Sum256(data);if n!=int64(len(data))||got!=hex.EncodeToString(want[:]){t.Fatalf("copy checksum mismatch: %d/%s",n,got)};actual,_:=os.ReadFile(dst);if string(actual)!=string(data){t.Fatal("target bytes differ")};relayDst:=filepath.Join(t.TempDir(),"relay-target.bin");if _,_,e=CopyWithMode("relay",src,relayDst);e!=nil{t.Fatal(e)}}
